     - Output pin to analog pin A2 (or whichever analog pin you're using)

2. **Arduino Sketch**: Here is a sample code that reads the values from the distance sensor and the light sensor and prints them to the serial monitor:

```cpp
const int DISTANCE_SENSOR_PIN = A1; // Pin connected to the Echo of the distance sensor
const int LIGHT_SENSOR_PIN = A2;     // Pin connected to the light sensor

void setup() {
    Serial.begin(9600); // Start serial communication for debugging
    pinMode(LIGHT_SENSOR_PIN, INPUT); // Set light sensor pin as input
    pinMode(DISTANCE_SENSOR_PIN, INPUT); // Set distance sensor pin as input
}

float getDistance_cm() {
    // You might need to change this implementation based on your distance sensor
    long duration;
    float distance;

    // Assuming you are using an ultrasonic sensor like HC-SR04
    pinMode(DISTANCE_SENSOR_PIN, OUTPUT);
    digitalWrite(DISTANCE_SENSOR_PIN, LOW);
    delayMicroseconds(2);
    digitalWrite(DISTANCE_SENSOR_PIN, HIGH);
    delayMicroseconds(10);
    digitalWrite(DISTANCE_SENSOR_PIN, LOW);
    pinMode(DISTANCE_SENSOR_PIN, INPUT);

    duration = pulseIn(DISTANCE_SENSOR_PIN, HIGH);
    distance = duration * 0.034 / 2; // Convert to cm
    return distance;
}

void loop() {
    float distance = getDistance_cm(); // Get the distance from the distance sensor
    int lightSensorValue = analogRead(LIGHT_SENSOR_PIN); // Read the light sensor value

    // Print both sensor values
    Serial.print("Distance (cm): ");
    Serial.print(distance);
    Serial.print("  Light Sensor Value: ");
    Serial.println(lightSensorValue);

    delay(500); // Delay for readability
}
```

